from collections import deque

def transform(grid):
 h,w=len(grid),len(grid[0]); cells={(r,c):grid[r][c] for r in range(h) for c in range(w) if grid[r][c]}
 seen=set(); comps=[]
 for pos,v in cells.items():
  if pos in seen: continue
  q=[pos]; seen.add(pos); comp=[]
  while q:
   r,c=q.pop(); comp.append((r,c,v))
   for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
    if p in cells and cells[p]==v and p not in seen: seen.add(p); q.append(p)
  comps.append(comp)
 # move components from rightmost to leftmost
 out=[[0]*w for _ in range(h)]
 comps.sort(key=lambda x:max(c for r,c,v in x),reverse=True)
 for comp in comps:
  shift=0
  while True:
   nxt=shift+1
   if any(c+nxt>=w or (out[r][c+nxt] and (r,c+nxt) not in {(rr,cc+shift) for rr,cc,vv in comp}) for r,c,v in comp): break
   shift=nxt
  for r,c,v in comp: out[r][c+shift]=v
 return out

